//! Lossless lexer (SPEC §2): every input byte belongs to exactly one token.
//!
//! The DFA is generated by `logos`; this module adds what a DFA can't say:
//! unterminated block comments, literal validation (L0002-L0005), and
//! merging runs of unrecognized input. Citations have no lexical mode: the
//! text after `cite` is an ordinary string literal (SPEC §2).
use crate::error::{range, SyntaxError};
use crate::suggest::nearest;
use crate::syntax_kind::SyntaxKind;
use litigate_base::{Applicability, DiagnosticCode};
use logos::Logos;
use rowan::TextRange;

/// One lexed token: its kind and byte range.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Token {
    /// Token kind; keywords other than `cite` are still [`SyntaxKind::Ident`].
    pub kind: SyntaxKind,
    /// Byte range in the source.
    pub range: TextRange,
}

#[derive(Logos, Debug, Clone, Copy, PartialEq, Eq)]
enum Raw {
    #[regex(r"[ \t\r\n]+")]
    Whitespace,
    #[regex(r"//[^\n]*")]
    LineComment,
    #[regex(r"///[^\n]*", priority = 10)]
    DocComment,
    #[token("/*")]
    BlockCommentStart,
    #[regex(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")]
    Date,
    #[regex(r"[0-9][0-9_]*(\.[0-9][0-9_]*)?\.[A-Za-z_][A-Za-z0-9_]*")]
    UnitLiteral,
    #[regex(r"[0-9][0-9_]*(\.[0-9][0-9_]*)?")]
    Number,
    #[regex(r#""([^"\\\n]|\\[^\n])*""#)]
    String,
    #[regex(r#""([^"\\\n]|\\[^\n])*\\?"#)]
    UnterminatedString,
    #[regex(r"[\p{XID_Start}_]\p{XID_Continue}*(-\p{XID_Continue}+)*")]
    // Digits then a letter start an identifier too (`12b-motion-filed`).
    #[regex(r"[0-9]+\p{XID_Start}\p{XID_Continue}*(-\p{XID_Continue}+)*")]
    Ident,
    #[token("_", priority = 10)]
    Underscore,
    #[token("::")]
    ColonColon,
    #[token("->")]
    Arrow,
    #[token("=>")]
    FatArrow,
    #[token("==")]
    EqEq,
    #[token("!=")]
    NotEq,
    #[token("<=")]
    LessEq,
    #[token(">=")]
    GreaterEq,
    #[token("&&")]
    AndAnd,
    #[token("||")]
    OrOr,
    #[token("..")]
    DotDot,
    #[regex(r"[{}()\[\]:,.=<>+\-*/%!?@^~|]")]
    Punct,
}

const DAY_SUFFIXES: [&str; 6] = [
    "days",
    "court_days",
    "business_days",
    "weeks",
    "months",
    "years",
];
const UNIT_SUFFIXES: [&str; 8] = [
    "days",
    "court_days",
    "business_days",
    "weeks",
    "months",
    "years",
    "hours",
    "usd",
];

/// Words reserved for constructs a later edition adds (SPEC §2): the
/// lexer reports each as L0007 wherever it appears as an identifier, so
/// no source written today can collide with that syntax.
pub const RESERVED_WORDS: [&str; 5] = ["world", "layer", "precedent", "overrule", "lock"];

/// Words reserved for the refinement surface syntax of the SMT tier
/// (SPEC §2.1): L0009 wherever they appear, in the grammar's `where`
/// clause slot as well as anywhere an identifier could stand.
pub const REFINEMENT_WORDS: [&str; 1] = ["where"];

/// Message prefix of every L0009 diagnostic (SPEC §2.1).
pub const RESERVED_REFINEMENT: &str = "reserved: refinements (SMT tier)";

/// The keywords of the typed guard operations of a patch (SPEC §3.6):
/// `when and p` narrows the patched edge's guard, `when or p` widens it.
/// They are keywords only in the grammar's `GuardOp` slot; anywhere else,
/// where an identifier could stand, they are L0010.
pub const GUARD_OP_WORDS: [&str; 2] = ["and", "or"];

/// Message prefix of every L0010 diagnostic (SPEC §3.6).
pub const RESERVED_GUARD_OP: &str = "reserved: guard-operation keyword";

/// Words reserved for filing requirements (SPEC §3.7): `limit` declares a
/// paper kind's length limits, `requires certificate` the certificates it
/// must carry, `excludes` what does not count toward a limit. L0011
/// wherever they appear, in the grammar's `limit` slot as well as anywhere
/// an identifier could stand. `requires` stays the edge field keyword.
pub const FILING_WORDS: [&str; 3] = ["limit", "certificate", "excludes"];

/// Message prefix of every L0011 diagnostic (SPEC §3.7).
pub const RESERVED_FILING: &str = "reserved: filing requirements";

/// Lexes `text` into a lossless token stream plus lexical errors.
#[must_use]
pub fn lex(text: &str) -> (Vec<Token>, Vec<SyntaxError>) {
    let mut out = Lexer {
        text,
        tokens: Vec::new(),
        errors: Vec::new(),
    };
    out.run();
    (out.tokens, out.errors)
}

struct Lexer<'t> {
    text: &'t str,
    tokens: Vec<Token>,
    errors: Vec<SyntaxError>,
}

impl Lexer<'_> {
    /// Records a token; every token is at least one byte long.
    fn push(&mut self, kind: SyntaxKind, start: usize, end: usize) {
        self.tokens.push(Token {
            kind,
            range: range(start, end),
        });
    }

    fn error(&mut self, code: DiagnosticCode, start: usize, end: usize, message: String) {
        self.errors
            .push(SyntaxError::new(code, range(start, end), message));
    }

    fn run(&mut self) {
        let mut raw = Raw::lexer(self.text);
        if self.text.starts_with('\u{feff}') {
            let end = '\u{feff}'.len_utf8();
            self.push(SyntaxKind::ErrorToken, 0, end);
            self.error(
                DiagnosticCode::InvalidToken,
                0,
                end,
                "byte order mark is not allowed; save the file as UTF-8 without BOM".into(),
            );
            raw.bump(end);
        }
        while let Some(result) = raw.next() {
            let span = raw.span();
            if let Ok(token) = result {
                let consumed = self.token(token, span.start, span.end, raw.remainder());
                raw.bump(consumed);
            } else {
                self.unrecognized(span.start, span.end);
            }
        }
    }

    /// Handles one raw token; returns how many extra bytes it consumed from
    /// `rest` (block comment bodies, glued identifiers).
    fn token(&mut self, token: Raw, start: usize, end: usize, rest: &str) -> usize {
        let text = &self.text[start..end];
        match token {
            Raw::Whitespace => self.push(SyntaxKind::Whitespace, start, end),
            Raw::LineComment => self.push(SyntaxKind::Comment, start, end),
            Raw::DocComment => self.push(SyntaxKind::DocComment, start, end),
            Raw::BlockCommentStart => return self.block_comment(start, end, rest),
            Raw::Date => return self.date(start, end, rest),
            Raw::UnitLiteral => self.unit_literal(start, end),
            Raw::Number => {
                self.check_digits(start, text);
                self.push(SyntaxKind::Number, start, end);
            }
            Raw::String => self.string(start, end, true),
            Raw::UnterminatedString => self.string(start, end, false),
            Raw::Ident if text == "cite" => self.push(SyntaxKind::KwCite, start, end),
            Raw::Ident => {
                if REFINEMENT_WORDS.contains(&text) {
                    self.error(
                        DiagnosticCode::ReservedRefinement,
                        start,
                        end,
                        format!(
                            "{RESERVED_REFINEMENT}: `{text}` introduces a refinement clause, which \
                             a later edition adds; it cannot be written or used as an identifier"
                        ),
                    );
                } else if GUARD_OP_WORDS.contains(&text) {
                    self.errors.push(
                        SyntaxError::new(
                            DiagnosticCode::ReservedGuardOp,
                            range(start, end),
                            format!(
                                "{RESERVED_GUARD_OP}: `{text}` combines a patched edge's guard \
                             only in `when {text} p` inside a `patch`; it cannot be used as an \
                             identifier"
                            ),
                        )
                        .with_fix(
                            range(start, end),
                            if text == "and" { "&&" } else { "||" },
                            Applicability::MachineApplicable,
                        ),
                    );
                } else if FILING_WORDS.contains(&text) {
                    self.error(
                        DiagnosticCode::ReservedFilingRequirement,
                        start,
                        end,
                        format!(
                            "{RESERVED_FILING}: `{text}` belongs to a paper's filing requirements \
                             (length limits, certificates, exclusions), which a later change adds; \
                             it cannot be written or used as an identifier"
                        ),
                    );
                } else if RESERVED_WORDS.contains(&text) {
                    self.error(
                        DiagnosticCode::ReservedWord,
                        start,
                        end,
                        format!(
                            "`{text}` is reserved for a future language construct and cannot be \
                             used as an identifier"
                        ),
                    );
                }
                self.push(SyntaxKind::Ident, start, end);
            }
            Raw::Underscore => self.push(SyntaxKind::Underscore, start, end),
            other => self.push(punct_kind(other, text), start, end),
        }
        0
    }

    /// Tokens tile the input, so an `ErrorToken` last token ends at `start`
    /// and the last error is the one reported for it.
    fn unrecognized(&mut self, start: usize, end: usize) {
        let last = self.tokens.last_mut();
        if let Some(last) = last.filter(|last| last.kind == SyntaxKind::ErrorToken) {
            last.range = range(usize::from(last.range.start()), end);
            let invalid = self.errors.last_mut();
            if let Some(error) = invalid.filter(|e| e.code == DiagnosticCode::InvalidToken) {
                error.range = last.range;
            }
            return;
        }
        self.push(SyntaxKind::ErrorToken, start, end);
        let shown = &self.text[start..end];
        self.error(
            DiagnosticCode::InvalidToken,
            start,
            end,
            format!("invalid character {shown:?}"),
        );
    }

    fn block_comment(&mut self, start: usize, end: usize, rest: &str) -> usize {
        if let Some(at) = rest.find("*/") {
            self.push(SyntaxKind::Comment, start, end + at + 2);
            at + 2
        } else {
            let stop = end + rest.len();
            self.push(SyntaxKind::Comment, start, stop);
            self.errors.push(
                SyntaxError::new(
                    DiagnosticCode::UnterminatedLiteral,
                    range(start, end),
                    "unterminated block comment",
                )
                .with_fix(
                    range(stop, stop),
                    "*/",
                    Applicability::MachineApplicable,
                ),
            );
            rest.len()
        }
    }

    fn date(&mut self, start: usize, end: usize, rest: &str) -> usize {
        let glued = rest
            .char_indices()
            .find(|(_, c)| !(c.is_alphanumeric() || *c == '_'))
            .map_or(rest.len(), |(at, _)| at);
        if glued > 0 {
            self.push(SyntaxKind::ErrorToken, start, end + glued);
            let text = &self.text[start..end + glued];
            self.error(
                DiagnosticCode::InvalidToken,
                start,
                end + glued,
                format!(
                    "`{text}` is not a date: a date may not be followed by identifier characters"
                ),
            );
            return glued;
        }
        let text = &self.text[start..end];
        if !valid_date(text) {
            self.error(
                DiagnosticCode::InvalidDate,
                start,
                end,
                format!("`{text}` is not a valid proleptic Gregorian date"),
            );
        }
        self.push(SyntaxKind::Date, start, end);
        0
    }

    fn unit_literal(&mut self, start: usize, end: usize) {
        let text = &self.text[start..end];
        let dot = text.rfind('.').unwrap_or(text.len());
        let (number, suffix) = (&text[..dot], text.get(dot + 1..).unwrap_or(""));
        self.check_digits(start, number);
        let kind = match suffix {
            "usd" => SyntaxKind::Money,
            "hours" => SyntaxKind::Duration,
            // Whole-day amounts are checked by the parser: `duration`
            // estimates may be decimal (SPEC §2).
            day if DAY_SUFFIXES.contains(&day) => SyntaxKind::Duration,
            _ => {
                let at = range(start + dot + 1, end);
                let mut error = SyntaxError::new(
                    DiagnosticCode::InvalidNumber,
                    at,
                    format!("unknown unit suffix `{suffix}`"),
                )
                .with_note(
                    "valid suffixes: usd, days, court_days, business_days, weeks, months, \
                     years, hours",
                );
                if let Some(best) = nearest(suffix, &UNIT_SUFFIXES) {
                    error = error.with_fix(at, best, Applicability::MachineApplicable);
                }
                self.errors.push(error);
                SyntaxKind::ErrorToken
            }
        };
        self.push(kind, start, end);
    }

    fn check_digits(&mut self, start: usize, number: &str) {
        let bad = number
            .split('.')
            .any(|part| part.ends_with('_') || part.contains("__"));
        if bad {
            self.error(
                DiagnosticCode::InvalidNumber,
                start,
                start + number.len(),
                format!("`{number}`: `_` is allowed only between two digits"),
            );
        }
    }

    fn string(&mut self, start: usize, end: usize, terminated: bool) {
        self.push(SyntaxKind::String, start, end);
        if !terminated {
            self.errors.push(
                SyntaxError::new(
                    DiagnosticCode::UnterminatedLiteral,
                    range(start, start + 1),
                    "unterminated string literal",
                )
                .with_fix(range(end, end), "\"", Applicability::MachineApplicable),
            );
        }
        let text = &self.text[start..end];
        let mut chars = text.char_indices().peekable();
        while let Some((at, c)) = chars.next() {
            if c != '\\' {
                continue;
            }
            match chars.next() {
                Some((_, '\\' | '"' | 'n' | 'r' | 't')) | None => {}
                Some((next, other)) => {
                    let stop = start + next + other.len_utf8();
                    self.error(
                        DiagnosticCode::InvalidToken,
                        start + at,
                        stop,
                        format!(
                            "invalid escape `\\{other}`; valid escapes are \\\\ \\\" \\n \\r \\t"
                        ),
                    );
                }
            }
        }
    }
}

fn punct_kind(token: Raw, text: &str) -> SyntaxKind {
    match token {
        Raw::ColonColon => SyntaxKind::ColonColon,
        Raw::Arrow => SyntaxKind::Arrow,
        Raw::FatArrow => SyntaxKind::FatArrow,
        Raw::EqEq => SyntaxKind::EqEq,
        Raw::NotEq => SyntaxKind::NotEq,
        Raw::LessEq => SyntaxKind::LessEq,
        Raw::GreaterEq => SyntaxKind::GreaterEq,
        Raw::AndAnd => SyntaxKind::AndAnd,
        Raw::OrOr => SyntaxKind::OrOr,
        Raw::DotDot => SyntaxKind::DotDot,
        _ => single_punct(text),
    }
}

/// The punctuation kind spelled `text` (keyword spellings are words, so
/// they never match a punctuation character).
fn single_punct(text: &str) -> SyntaxKind {
    SyntaxKind::ALL
        .iter()
        .copied()
        .find(|kind| kind.text() == Some(text))
        .unwrap_or(SyntaxKind::ErrorToken)
}

/// True when `text` (`YYYY-MM-DD`) is a valid proleptic Gregorian date.
#[must_use]
pub fn valid_date(text: &str) -> bool {
    let mut parts = text.split('-').map(str::parse::<u32>);
    let (Some(Ok(year)), Some(Ok(month)), Some(Ok(day)), None) =
        (parts.next(), parts.next(), parts.next(), parts.next())
    else {
        return false;
    };
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    let days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => return false,
    };
    (1..=days).contains(&day)
}

